     4→
     5→export interface SeoSettings {
     6→  id: string;
     7→  site_title: string;
     8→  site_description: string;
     9→  site_keywords: string;
    10→  canonical_url: string;
    11→  og_title: string;
    12→  og_description: string;
    13→  og_image_url: string;
    14→  og_type: string;
    15→  og_site_name: string;
    16→  twitter_card: string;
    17→  twitter_site: string;
    18→  twitter_creator: string;
    19→  twitter_image_url: string;
    20→  robots_txt: string;
    21→  meta_robots: string;
    22→  googlebot: string;
    23→  bingbot: string;
    24→  sitemap_enabled: boolean;
    25→  sitemap_changefreq: string;
    26→  sitemap_priority: number;
    27→  structured_data_enabled: boolean;
    28→  organization_name: string;
    29→  organization_url: string;
    30→  organization_logo_url: string;
    31→  organization_description: string;
    32→  google_analytics_id: string;
    33→  google_search_console_id: string;
    34→  bing_webmaster_id: string;
    35→  facebook_app_id: string;
    36→  theme_color: string;
    37→  manifest_enabled: boolean;
    38→  created_at: string;
    39→  updated_at: string;
    40→}
    41→
    42→export interface SeoPage {
    43→  id: string;
    44→  page_path: string;
    45→  page_name: string;
    46→  title: string;
    47→  description: string;
    48→  keywords: string;
    49→  og_title: string;
    50→  og_description: string;
    51→  og_image_url: string;
    52→  meta_robots: string;
    53→  canonical_url: string;
    54→  structured_data_json: Record<string, any>;
    55→  changefreq: string;
    56→  priority: number;
    57→  include_in_sitemap: boolean;
    58→  is_active: boolean;
    59→  created_at: string;
    60→  updated_at: string;
    61→}
    62→
    63→export function useSeoSettings() {
    64→  const qc = useQueryClient();
    65→
    66→  const { data: settings, isLoading } = useQuery({
    67→    queryKey: ["seo_settings"],
    68→    queryFn: async () => {
    69→      const { data, error } = await (supabase as any)
    70→        .from("seo_settings")
    71→        .select("*")
    72→        .limit(1)
    73→        .single();
    74→      if (error) throw error;
    75→      return data as SeoSettings;
    76→    },
    77→    staleTime: 60_000,
    78→  });
    79→
    80→  useEffect(() => {
    81→    const channel = supabase
    82→      .channel("seo_settings_realtime")
    83→      .on(
    84→        "postgres_changes",
    85→        { event: "*", schema: "public", table: "seo_settings" },
    86→        () => {
    87→          qc.invalidateQueries({ queryKey: ["seo_settings"] });
    88→        }
    89→      )
    90→      .subscribe();
    91→
    92→    return () => {
    93→      supabase.removeChannel(channel);
    94→    };
    95→  }, [qc]);
    96→
    97→  return { settings, isLoading };
    98→}
    99→
   100→export function useSeoPages() {
   101→  const qc = useQueryClient();
   102→
   103→  const { data: pages, isLoading } = useQuery({
   104→    queryKey: ["seo_pages"],
   105→    queryFn: async () => {
   106→      const { data, error } = await (supabase as any)
   107→        .from("seo_pages")
   108→        .select("*")
   109→        .order("page_path");
   110→      if (error) throw error;
   111→      return data as SeoPage[];
   112→    },
   113→    staleTime: 60_000,
   114→  });
   115→
   116→  useEffect(() => {
   117→    const channel = supabase
   118→      .channel("seo_pages_realtime")
   119→      .on(
   120→        "postgres_changes",
   121→        { event: "*", schema: "public", table: "seo_pages" },
   122→        () => {
   123→          qc.invalidateQueries({ queryKey: ["seo_pages"] });
   124→        }
   125→      )
   126→      .subscribe();
   127→
   128→    return () => {
   129→      supabase.removeChannel(channel);
   130→    };
   131→  }, [qc]);
   132→
   133→  return { pages: pages ?? [], isLoading };
   134→}
   135→
   136→export function useSeoPageByPath(path: string) {
   137→  const { pages, isLoading } = useSeoPages();
   138→  const page = pages.find((p) => p.page_path === path);
   139→  return { page, isLoading };
   140→}
